Given an n × n chessboard. The task is to check if the given chessboard is valid or not. A chess board is considered valid if every 2 adjacent cells are painted differently. Two cells are considered adjacent if they share a boundary. Examples: Input : n = 2, C = [ [ 1, 0 ], [ 0, 1 ] ]Output : YesExplanation: All adjacent cells are painted differently hence a valid chessboard. Input : n = 2,  C = [ [ 1, 0 ], [ 0, 0 ]]  Output : NoExplanation: All adjacent cells are not painted differently hence not a valid chessboard. The first chessboard is valid, whereas the second is invalid.[Naive Approach]  - Checking all adjacent CellsThis idea for this approach is to verify that each cell on the grid has a different color than its directly adjacent neighbors. For a given cell (i, j), its adjacent cells are the ones directly above, below, left, and right, i.e., (i + 1, j), (i - 1, j), (i, j + 1), and (i, j - 1)
            C++

    #include <bits/stdc++.h>
using namespace std;

// Check if the given chess board is valid or not.
bool isValid(vector<vector<int>>& c, int n)
{
    int X[] = { 0, -1, 0, 1 };
    int Y[] = { 1, 0, -1, 0 };
    bool isValid = true;

    // Traversing each cell of the chess board.
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {

            // for each adjacent cells
            for (int k = 0; k < 4; k++) {
                int newX = i + X[k];
                int newY = j + Y[k];

                // checking if they have different color
                if (newX < n && newY < n && newX >= 0 && 
                    newY >= 0 && c[newX][newY] == c[i][j]) {
                    isValid = false;
                }
            }
        }
    }
    return isValid;
}

int main()
{
    int n = 2;
    vector<vector<int>> c = { { 1, 0 },
                                { 0, 1 } };

    (isValid(c, n)) ? (cout << "Yes") : (cout << "No");
    return 0;
}


